const chatInput = $input.first().json.chatInput || '';
const dates = chatInput.match(/(\d{4}-\d{2}-\d{2})/g) || [];
const today = new Date();
const ago90 = new Date(today);
ago90.setDate(today.getDate() - 90);
return [{
  json: {
    chatInput,
    dateRangeStart: dates[0] || ago90.toISOString().split('T')[0],
    dateRangeEnd:   dates[1] || today.toISOString().split('T')[0]
  }
}];

// Queries ran sequentially — all node outputs are available by name.
const daily     = $('Supabase - Daily Aggregates').all().map(i => i.json);
const planBreak = $('Supabase - Plan & Method Breakdown').all().map(i => i.json);
const trends    = $('Supabase - Monthly Trends').all().map(i => i.json);
const byCountry = $('Supabase - Customer Revenue by Country').all().map(i => i.json);
const parsed    = $('Parse Chat Input').first().json;

function linearRegression(rows, field) {
  const y = rows.map(r => parseFloat(r[field]) || 0);
  const n = y.length;
  if (n < 2) return { slope: 0, intercept: y[0] || 0, r2: 0 };
  const x = y.map((_, i) => i);
  const xm = x.reduce((a, b) => a + b, 0) / n;
  const ym = y.reduce((a, b) => a + b, 0) / n;
  const num = x.reduce((s, xi, i) => s + (xi - xm) * (y[i] - ym), 0);
  const den = x.reduce((s, xi) => s + (xi - xm) ** 2, 0);
  const slope = den ? num / den : 0;
  const intercept = ym - slope * xm;
  const ssRes = y.reduce((s, yi, i) => s + (yi - (slope * i + intercept)) ** 2, 0);
  const ssTot = y.reduce((s, yi) => s + (yi - ym) ** 2, 0);
  return {
    slope:     Math.round(slope * 100) / 100,
    intercept: Math.round(intercept * 100) / 100,
    r2:        ssTot ? Math.round((1 - ssRes / ssTot) * 1000) / 1000 : 1
  };
}

const reg     = linearRegression(trends, 'completed_amount');
const predict = n => Math.round((reg.slope * n + reg.intercept) * 100) / 100;
const sumF    = (rows, f) => Math.round(rows.reduce((s, r) => s + parseFloat(r[f] || 0), 0) * 100) / 100;

const totalRevenue = sumF(trends, 'completed_amount');
const totalPending = sumF(trends, 'pending_amount');
const totalFailed  = sumF(trends, 'failed_amount');
const totalAll     = sumF(trends, 'monthly_total');
const failureRate  = totalAll > 0 ? Math.round((totalFailed / totalAll) * 10000) / 100 : 0;

// Top plan by completed revenue
const planRevenue = {};
planBreak.filter(r => r.payment_status === 'completed').forEach(r => {
  const k = r.plan || 'unknown';
  planRevenue[k] = (planRevenue[k] || 0) + parseFloat(r.total_amount || 0);
});
const topPlanEntry = Object.entries(planRevenue).sort((a, b) => b[1] - a[1])[0] || null;

// Plan anomalies: failure rate > 20%
const planTotals = {};
const planFailed = {};
planBreak.forEach(r => {
  const k = r.plan || 'unknown';
  planTotals[k] = (planTotals[k] || 0) + parseInt(r.transaction_count || 0);
  if (r.payment_status === 'failed') planFailed[k] = (planFailed[k] || 0) + parseInt(r.transaction_count || 0);
});
const planAnomalies = Object.entries(planTotals)
  .map(([plan, total]) => ({ plan, failureRate: Math.round(((planFailed[plan] || 0) / total) * 10000) / 100 }))
  .filter(p => p.failureRate > 20);

// Trend direction — guard against empty trends
const last = trends.length > 0 ? trends[trends.length - 1] : null;
const momChange = last ? parseFloat(last.mom_pct_change || 0) : 0;
const trendDirection = !last ? 'unknown' : momChange > 0 ? 'upward' : momChange < 0 ? 'downward' : 'stable';

return [{
  json: {
    chatInput:      parsed.chatInput,
    dateRangeStart: parsed.dateRangeStart,
    dateRangeEnd:   parsed.dateRangeEnd,
    daily,
    planBreakdown:  planBreak,
    trends,
    byCountry,
    analysis: {
      totalRevenue,
      totalPending,
      totalFailed,
      totalAll,
      failureRate,
      topPlan:         topPlanEntry ? { plan: topPlanEntry[0], revenue: Math.round(topPlanEntry[1] * 100) / 100 } : null,
      topCountry:      byCountry.length > 0 ? { country: byCountry[0].country, revenue: parseFloat(byCountry[0].total_revenue || 0) } : null,
      trendDirection,
      latestMoMGrowth: momChange,
      planAnomalies,
      regression: reg,
      predictions: {
        nextMonth:    predict(trends.length),
        twoMonthsOut: predict(trends.length + 1)
      }
    }
  }
}];

// Build the full OpenAI request body as a JSON string.
// Using a Code node keeps the HTTP Request node simple and avoids
// complex expression syntax in non-code fields.
const d = $input.first().json;
const a = d.analysis;

const systemPrompt = 'You are an expert financial analyst AI embedded in a chat interface. ' +
  'You receive pre-computed revenue and payment data from a SaaS business and the user question.\n\n' +
  'Your response must:\n' +
  '1. Directly answer the user question with specific numbers.\n' +
  '2. Provide key insights: revenue health, plan performance, top markets.\n' +
  '3. Highlight the payment failure rate and any plan-level anomalies.\n' +
  '4. Give a clear revenue prediction for the next 1-2 months with a confidence note based on R2 score.\n' +
  '5. Provide 2-3 concrete, actionable recommendations.\n\n' +
  'Format as clean Markdown with headers and summary tables. Be direct and data-driven.';

const userPrompt =
  'User question: ' + d.chatInput + '\n\n' +
  'Date range: ' + d.dateRangeStart + ' to ' + d.dateRangeEnd + '\n\n' +
  '## Revenue Summary\n' +
  '- Completed revenue: $' + a.totalRevenue + '\n' +
  '- Pending: $' + a.totalPending + '\n' +
  '- Failed: $' + a.totalFailed + '\n' +
  '- Failure rate: ' + a.failureRate + '%\n' +
  '- Top plan: ' + (a.topPlan ? a.topPlan.plan + ' ($' + a.topPlan.revenue + ')' : 'N/A') + '\n' +
  '- Top country: ' + (a.topCountry ? a.topCountry.country + ' ($' + a.topCountry.revenue + ')' : 'N/A') + '\n' +
  '- Trend: ' + a.trendDirection + ' (' + a.latestMoMGrowth + '% MoM)\n\n' +
  '## Plan & Payment Method Breakdown\n' + JSON.stringify(d.planBreakdown, null, 2) + '\n\n' +
  '## Monthly Trends\n' + JSON.stringify(d.trends, null, 2) + '\n\n' +
  '## Revenue by Country & Plan\n' + JSON.stringify(d.byCountry, null, 2) + '\n\n' +
  '## Plan Anomalies (failure rate > 20%)\n' + JSON.stringify(a.planAnomalies, null, 2) + '\n\n' +
  '## Regression Model (completed revenue)\n' +
  'Slope: ' + a.regression.slope + ', R2: ' + a.regression.r2 + '\n\n' +
  '## Predictions\n' +
  '- Next month: $' + a.predictions.nextMonth + '\n' +
  '- Two months out: $' + a.predictions.twoMonthsOut + '\n\n' +
  'Please generate the financial report.';

return [{
  json: {
    ...d,
    openAiBody: JSON.stringify({
      model: 'gpt-4o',
      temperature: 0.3,
      max_tokens: 2000,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userPrompt }
      ]
    })
  }
}];

// OpenAI raw API response: choices[0].message.content
const reportContent = $input.first().json.choices[0].message.content;
const ctx = $('Build OpenAI Prompt').first().json;
return [{
  json: {
    reportId:        'RPT-' + Date.now(),
    generatedAt:     new Date().toISOString(),
    chatInput:       ctx.chatInput,
    dateRangeStart:  ctx.dateRangeStart,
    dateRangeEnd:    ctx.dateRangeEnd,
    reportContent,
    analysisSummary: ctx.analysis
  }
}];
